def safe(s):
    s=re.sub(r'(?i)\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\b',lambda m:'sha256-guid:'+hashlib.sha256(m.group().encode()).hexdigest(),s)
    return re.sub(r'(?i)(?<![0-9a-f])[0-9a-f]{32}(?![0-9a-f])',lambda m:'sha256-id:'+hashlib.sha256(m.group().encode()).hexdigest(),s)
